            g.insert(0, self._blank_row())

    def handle_sgr(self, params):
        if not params:
            params = [0]
        fg, bg, bold, dim, it, ul, st, bl, rev, hid = self.attr
        i = 0
        while i < len(params):
            p = params[i]
            if p == 0:
                fg, bg, bold, dim, it, ul, st, bl, rev, hid = DEFAULT_ATTR
            elif p == 1: bold = True
            elif p == 2: dim = True
            elif p == 3: it = True
            elif p == 4: ul = True
            elif p == 5: bl = True
            elif p == 7: rev = True
            elif p == 8: hid = True
