from snap import snap
from vtparse import Screen
for (r,c) in [(20,60),(30,100),(50,160)]:
    out, s = snap(f'create_{c}x{r}', stdin_after=[(b'n', 0.4)], rows=r, cols=c, quiet=True, save_raw=False)
    lines = s.render().split('\n')
    trow = tcol = None
    for i,l in enumerate(lines):
        p = l.find('┌Create journal')
        if p >= 0:
            trow, tcol = i+1, p+1
            break
    brow = None
    for i in range(trow or 0, len(lines)):
        if lines[i].startswith('└', tcol-1) if tcol else False:
            brow = i+1
            break
    print(f'{c}x{r}: top=({trow},{tcol}) bottom_row={brow}')
    if trow: print('   ', repr(lines[trow-1]))
    if brow: print('   ', repr(lines[brow-1]))
" 2>&1

